export default "import {\n  CustomVariable,\n  EmbeddedScene,\n  PanelBuilders,\n  SceneAppPage,\n  SceneAppPageState,\n  SceneFlexItem,\n  SceneFlexLayout,\n  SceneVariableSet,\n  VariableValueSelectors,\n} from '@grafana/scenes';\nimport { getEmbeddedSceneDefaults } from './utils';\n\nexport function getVariableWithObjectValuesDemo(defaults: SceneAppPageState) {\n  return new SceneAppPage({\n    ...defaults,\n    getScene: () => {\n      return new EmbeddedScene({\n        ...getEmbeddedSceneDefaults(),\n        controls: [new VariableValueSelectors({})],\n        $variables: new SceneVariableSet({\n          variables: [\n            new CustomVariable({\n              name: 'envs',\n              label: 'Environments',\n              isMulti: true,\n              includeAll: true,\n              valuesFormat: 'json',\n              query: `\n[\n  { \"value\": \"1\", \"text\": \"Development\",  \"aws_environment\": \"development\", \"azure_environment\": \"dev\" },\n  { \"value\": \"2\", \"text\": \"Staging\",      \"aws_environment\": \"staging\",     \"azure_environment\": \"stg\" },\n  { \"value\": \"3\", \"text\": \"Production\",   \"aws_environment\": \"prod\",        \"azure_environment\": \"prd\" }\n]\n`,\n            }),\n          ],\n        }),\n        body: new SceneFlexLayout({\n          children: [\n            new SceneFlexItem({\n              body: PanelBuilders.text().setTitle('AWS').setOption('content', '${envs.aws_environment}').build(),\n            }),\n            new SceneFlexItem({\n              body: PanelBuilders.text().setTitle('Azure').setOption('content', '${envs.azure_environment}').build(),\n            }),\n          ],\n        }),\n      });\n    },\n  });\n}\n";